    ('july-27', 'july-27-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-27-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"taste","isOriginal":false,"hint":"Read the full sentence before you answer.","hintJa":"文全体を確認して答えましょう。","explanation":"This dessert has a sophisticated flavor.","explanationJa":"このデザートは洗練された味です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"This dessert has a sophisticated flavor.","jp":"このデザートは洗練された味です。"},{"id":"b","en":"He plays tennis every week.","jp":"彼は毎週テニスをします。"},{"id":"c","en":"I went to Malaysia last year.","jp":"去年マレーシアに行きました。"},{"id":"d","en":"I have been to Malaysia.","jp":"マレーシアへ行ったことがあります。"}],"correct":"a","image":"/assets/questions/visual/july-27-05-sophisticated-dessert.webp","imageAlt":"An elegant dessert has a sophisticated flavor.","visualAssetId":"july-27-05"}'::jsonb, false, 1)
) as source (
  lesson_slug, stable_key, position, section, format, payload,
  is_original, points
)
join public.review_lessons lesson on lesson.slug = source.lesson_slug
on conflict (lesson_id, stable_key) do update set
  position = excluded.position,
  section = excluded.section,
  format = excluded.format,
  payload = excluded.payload,
  is_original = excluded.is_original,
  points = excluded.points,
  active = true;

update public.review_lessons
set content_version = greatest(content_version, 2),
    content = jsonb_set(content, '{draft_questions}', '31'::jsonb, true),
    updated_at = now()
where slug in (
  'july-07', 'july-11', 'july-12', 'july-13', 'july-18', 'july-19',
  'july-22', 'july-23', 'july-25', 'july-26', 'july-27'
);
